from pathlib import Path
p=Path('/mnt/data/v35work/src/kernel.c')
s=p.read_text()
s=s.replace('#define MT_STACK_A_PAGE  0x003fd000u\n#define MT_STACK_A_TOP   0x003fdfe0u\n#define MT_STACK_B_PAGE  0x003fc000u\n#define MT_STACK_B_TOP   0x003fcfe0u\n#define MT_CONTEXT_WORDS 19u', '#define MT_STACK_PAGE    0x003fd000u\n#define MT_STACK_TOP     0x003fdfe0u\n#define MT_STACK_A_PHYS  0x003fd000u\n#define MT_STACK_B_PHYS  0x003fc000u\n#define MT_CONTEXT_WORDS 19u')
s=s.replace('static uint32_t page_directory[1024] __attribute__((aligned(4096)));\nstatic uint32_t page_table0[1024] __attribute__((aligned(4096)));', 'static uint32_t page_directory[1024] __attribute__((aligned(4096)));\nstatic uint32_t page_table0[1024] __attribute__((aligned(4096)));\n/* v35: A and B have separate CR3 roots and page tables.  The user virtual\n   layout is intentionally identical; only the physical stack backing differs. */\nstatic uint32_t mt_page_directory[2][1024] __attribute__((aligned(4096)));\nstatic uint32_t mt_page_table[2][1024] __attribute__((aligned(4096)));')
s=s.replace('static void paging_mark_user_ro(uint32_t start,uint32_t end){\n    uint32_t p;\n    start&=~0xfffu;\n    end=(end+0xfffu)&~0xfffu;\n    for(p=start;p<end&&p<0x00400000u;p+=0x1000u){page_table0[p>>12]|=PAGE_US;page_table0[p>>12]&=~PAGE_RW;}\n}', '''static void paging_mark_user_ro_table(uint32_t*pt,uint32_t start,uint32_t end){\n    uint32_t p;\n    start&=~0xfffu;\n    end=(end+0xfffu)&~0xfffu;\n    for(p=start;p<end&&p<0x00400000u;p+=0x1000u){pt[p>>12]|=PAGE_US;pt[p>>12]&=~PAGE_RW;}\n}\nstatic void paging_mark_user_ro(uint32_t start,uint32_t end){paging_mark_user_ro_table(page_table0,start,end);}\nstatic void paging_build_mt(void){\n    uint32_t t,i;\n    for(t=0;t<2u;t++){\n        mem_set(mt_page_directory[t],0,sizeof(mt_page_directory[t]));\n        mem_set(mt_page_table[t],0,sizeof(mt_page_table[t]));\n        for(i=0;i<1024u;i++)mt_page_table[t][i]=(i<<12)|PAGE_P|PAGE_RW;\n        mt_page_directory[t][0]=(uint32_t)mt_page_table[t]|PAGE_P|PAGE_RW|PAGE_US;\n        paging_mark_user_ro_table(mt_page_table[t],(uint32_t)__user_text_start,(uint32_t)__user_text_end);\n        paging_mark_user_ro_table(mt_page_table[t],(uint32_t)__user_rodata_start,(uint32_t)__user_rodata_end);\n        /* Same virtual stack address in both spaces, different physical page. */\n        mt_page_table[t][MT_STACK_PAGE>>12]=(t==0u?MT_STACK_A_PHYS:MT_STACK_B_PHYS)|PAGE_P|PAGE_RW|PAGE_US;\n    }\n}''')
s=s.replace('    page_table0[MT_STACK_A_PAGE>>12]=MT_STACK_A_PAGE|PAGE_P|PAGE_RW|PAGE_US;\n    page_table0[MT_STACK_B_PAGE>>12]=MT_STACK_B_PAGE|PAGE_P|PAGE_RW|PAGE_US;\n    __asm__ volatile("movl %0,%%cr3"::"r"((uint32_t)page_directory):"memory");', '    paging_build_mt();\n    __asm__ volatile("movl %0,%%cr3"::"r"((uint32_t)page_directory):"memory");')
s=s.replace('/* v34 experiment: two Ring-3 contexts in the SAME address space.  The IRQ0\n   handler saves the interrupted architectural frame and replaces it with the\n   other task frame.  No CR3 switch and no per-task page directory exist yet.\n   The 19 words include the two CPL3 words (ESP, SS) that follow struct frame. */\nstruct mt_context { uint32_t words[MT_CONTEXT_WORDS]; };', '/* v35 experiment: two Ring-3 contexts with separate CR3/address spaces.\n   The 19 words include the two CPL3 words (ESP, SS) that follow struct frame.\n   Both spaces use the same virtual stack address, backed by different physical\n   pages, so the experiment tests real address-space switching rather than only\n   register switching. */\nstruct mt_context { uint32_t words[MT_CONTEXT_WORDS]; uint32_t cr3; };')
s=s.replace('static uint32_t mt_saved_shell[MT_CONTEXT_WORDS];\nstatic uint32_t mt_start_tick;', 'static uint32_t mt_saved_shell[MT_CONTEXT_WORDS];\nstatic uint32_t mt_saved_shell_cr3;\nstatic uint32_t mt_start_tick;')
s=s.replace('    if(p>=MT_STACK_A_PAGE&&end<=MT_STACK_A_PAGE+0x1000u&&mt_active)return 1;\n    if(p>=MT_STACK_B_PAGE&&end<=MT_STACK_B_PAGE+0x1000u&&mt_active)return 1;', '    if(p>=MT_STACK_PAGE&&end<=MT_STACK_PAGE+0x1000u&&mt_active)return 1;')
s=s.replace('    if(mt_active&&p>=MT_STACK_A_PAGE&&end<=MT_STACK_A_PAGE+0x1000u)return 1;\n    if(mt_active&&p>=MT_STACK_B_PAGE&&end<=MT_STACK_B_PAGE+0x1000u)return 1;', '    if(mt_active&&p>=MT_STACK_PAGE&&end<=MT_STACK_PAGE+0x1000u)return 1;')
s=s.replace('static void mt_load_initial(struct mt_context*c,uint32_t entry,uint32_t esp){\n    mem_set(c,0,sizeof(*c));', 'static uint32_t read_cr3(void){uint32_t v;__asm__ volatile("movl %%cr3,%0":"=r"(v));return v;}\nstatic void load_cr3(uint32_t v){__asm__ volatile("movl %0,%%cr3"::"r"(v):"memory");}\nstatic void mt_load_initial(struct mt_context*c,uint32_t entry,uint32_t esp,uint32_t cr3){\n    mem_set(c,0,sizeof(*c));\n    c->cr3=cr3;')
s=s.replace('    mem_copy(mt_saved_shell,w,MT_CONTEXT_WORDS*4u);\n    mt_saved_shell[7]=0;\n    mt_load_initial(&mt_tasks[0],(uint32_t)&mt_task_a,MT_STACK_A_TOP);\n    mt_load_initial(&mt_tasks[1],(uint32_t)&mt_task_b,MT_STACK_B_TOP);', '    mem_copy(mt_saved_shell,w,MT_CONTEXT_WORDS*4u);\n    mt_saved_shell[7]=0;\n    mt_saved_shell_cr3=read_cr3();\n    mt_load_initial(&mt_tasks[0],(uint32_t)&mt_task_a,MT_STACK_TOP,(uint32_t)mt_page_directory[0]);\n    mt_load_initial(&mt_tasks[1],(uint32_t)&mt_task_b,MT_STACK_TOP,(uint32_t)mt_page_directory[1]);')
s=s.replace('    mt_active=1;\n    mem_copy(w,mt_tasks[0].words,MT_CONTEXT_WORDS*4u);', '    mt_active=1;\n    load_cr3(mt_tasks[0].cr3);\n    mem_copy(w,mt_tasks[0].words,MT_CONTEXT_WORDS*4u);')
s=s.replace('    mt_active=0;\n    mem_copy((uint32_t*)f,mt_saved_shell,MT_CONTEXT_WORDS*4u);', '    mt_active=0;\n    load_cr3(mt_saved_shell_cr3);\n    mem_copy((uint32_t*)f,mt_saved_shell,MT_CONTEXT_WORDS*4u);')
s=s.replace('    mt_current=next;\n    mem_copy((void*)f,mt_tasks[mt_current].words,MT_CONTEXT_WORDS*4u);', '    mt_current=next;\n    load_cr3(mt_tasks[mt_current].cr3);\n    mem_copy((void*)f,mt_tasks[mt_current].words,MT_CONTEXT_WORDS*4u);')
p.write_text(s)

